const input = $input.first().json;

// Build notification messages
const categoryEmoji = { hot: '🔴🔥', warm: '🟡', cold: '🔵' }[input.lead_category] || '⚪';
const emoji = categoryEmoji;

const telegramMsg = `${emoji} <b>NEW ${(input.lead_category || 'LEAD').toUpperCase()} LEAD — Synergistic AI</b>\n\n` +
  `👤 <b>Name:</b> ${input.first_name || 'Unknown'} ${input.last_name || ''}\n` +
  `🏢 <b>Company:</b> ${input.company || 'N/A'}\n` +
  `📧 <b>Email:</b> ${input.business_email || 'N/A'}\n` +
  `📱 <b>Phone:</b> ${input.phone_number || 'N/A'}\n` +
  `🌐 <b>Website:</b> ${input.company_website || 'N/A'}\n` +
  `🏭 <b>Industry:</b> ${input.industry || 'N/A'}\n` +
  `👥 <b>Employees:</b> ${input.employee_count || 'N/A'}\n` +
  `💰 <b>Budget:</b> ${input.monthly_budget || 'N/A'}\n` +
  `⚡ <b>Urgency:</b> ${input.urgency || 'N/A'}\n` +
  `🎯 <b>Service:</b> ${input.service_interest || 'N/A'}\n` +
  `📊 <b>Lead Score:</b> ${input.lead_score || 0}/100\n\n` +
  `💬 <b>Challenge:</b> ${input.business_challenge || 'N/A'}\n\n` +
  `🔗 <a href="https://app.hubspot.com/contacts/${input.hubspot_contact_id}">View in HubSpot</a>`;

const slackMsg = {
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: `${emoji} New ${(input.lead_category || 'Lead').charAt(0).toUpperCase() + (input.lead_category || 'lead').slice(1)} Lead — Synergistic AI` }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Name:*\n${input.first_name || 'Unknown'} ${input.last_name || ''}` },
        { type: 'mrkdwn', text: `*Company:*\n${input.company || 'N/A'}` },
        { type: 'mrkdwn', text: `*Email:*\n${input.business_email || 'N/A'}` },
        { type: 'mrkdwn', text: `*Budget:*\n${input.monthly_budget || 'N/A'}` },
        { type: 'mrkdwn', text: `*Urgency:*\n${input.urgency || 'N/A'}` },
        { type: 'mrkdwn', text: `*Lead Score:*\n${input.lead_score || 0}/100` }
      ]
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*Business Challenge:*\n${input.business_challenge || 'N/A'}` }
    },
    {
      type: 'actions',
      elements: [{
        type: 'button',
        text: { type: 'plain_text', text: 'View in HubSpot' },
        url: `https://app.hubspot.com/contacts/${input.hubspot_contact_id}`,
        style: 'primary'
      }]
    }
  ]
};

const emailSubject = `${emoji} ${(input.lead_category || 'New').toUpperCase()} LEAD: ${input.first_name || 'Unknown'} from ${input.company || 'Unknown Company'} (Score: ${input.lead_score || 0}/100)`;

const emailBody = `
<html><body style="font-family:Arial,sans-serif;">
<h2 style="color:#1E3A5F;">${emoji} New ${(input.lead_category || 'lead').charAt(0).toUpperCase() + (input.lead_category || 'lead').slice(1)} Lead Alert</h2>
<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%;">
<tr style="background:#1E3A5F;color:#fff;"><th>Field</th><th>Value</th></tr>
<tr><td><b>Name</b></td><td>${input.first_name || 'Unknown'} ${input.last_name || ''}</td></tr>
<tr style="background:#f5f5f5;"><td><b>Company</b></td><td>${input.company || 'N/A'}</td></tr>
<tr><td><b>Email</b></td><td>${input.business_email || 'N/A'}</td></tr>
<tr style="background:#f5f5f5;"><td><b>Phone</b></td><td>${input.phone_number || 'N/A'}</td></tr>
<tr><td><b>Industry</b></td><td>${input.industry || 'N/A'}</td></tr>
<tr style="background:#f5f5f5;"><td><b>Employees</b></td><td>${input.employee_count || 'N/A'}</td></tr>
<tr><td><b>Budget</b></td><td>${input.monthly_budget || 'N/A'}</td></tr>
<tr style="background:#f5f5f5;"><td><b>Urgency</b></td><td>${input.urgency || 'N/A'}</td></tr>
<tr><td><b>Service Interest</b></td><td>${input.service_interest || 'N/A'}</td></tr>
<tr style="background:#f5f5f5;"><td><b>Lead Score</b></td><td><b>${input.lead_score || 0}/100</b></td></tr>
</table>
<p><b>Business Challenge:</b><br>${input.business_challenge || 'N/A'}</p>
<p><a href="https://app.hubspot.com/contacts/${input.hubspot_contact_id}" style="background:#1E3A5F;color:#fff;padding:12px 24px;text-decoration:none;border-radius:4px;">View in HubSpot →</a></p>
</body></html>`;

return [{
  json: {
    ...input,
    telegram_msg: telegramMsg,
    slack_msg: JSON.stringify(slackMsg),
    email_subject: emailSubject,
    email_body: emailBody,
    is_hot: input.lead_category === 'hot',
    is_escalation: input.event_type === 'human_escalation'
  }
}];

